/**
 * @summary List memes generated for a specific fact
 */
export const ListFactMemesParams = zod.object({
  factId: zod.coerce.number().int(),
});

export const listFactMemesQuerySortDefault = `top`;

export const ListFactMemesQueryParams = zod.object({
  sort: zod
    .enum(["top", "new"])
    .default(listFactMemesQuerySortDefault)
    .describe(
      "Result ordering. `top` (default) ranks by heart count, then\ncreatedAt as tiebreak. `new` orders strictly by createdAt\ndescending.\n",
    ),
});

export const listFactMemesResponseMemesItemHeartCountMin = 0;

export const ListFactMemesResponse = zod.object({
  memes: zod.array(
    zod.object({
      id: zod.number().int(),
      factId: zod.number().int(),
      templateId: zod.string(),
      imageUrl: zod.string(),
      permalinkSlug: zod.string(),
      createdAt: zod.coerce.date(),
      heartCount: zod
        .number()
        .int()
        .min(listFactMemesResponseMemesItemHeartCountMin),
      viewerHasHearted: zod.boolean(),
    }),
  ),
});

/**
 * Accepts a JSON array of fact objects (or `{ "facts": [...] }`) and queues
 * each valid one as a Stage-1 moderation review (a system import — this
 * loads the moderation queue, it does not publish facts directly). Protected
 * by the `X-API-Key` header (ADMIN_API_KEY secret). Supports `?dryRun=true`
 * to validate without writing.
 * @summary Bulk-import facts for moderation (API key required)
 */
export const BulkImportFactsQueryParams = zod.object({
  dryRun: zod.coerce
    .boolean()
    .optional()
    .describe("If true, validate items but do not write to the database."),
});

export const bulkImportFactsBodyOneItemTextMin = 10;
export const bulkImportFactsBodyOneItemTextMax = 1000;

export const bulkImportFactsBodyOneItemHashtagsItemMax = 100;

export const bulkImportFactsBodyOneItemHashtagsItemRegExp = new RegExp(
  "^[a-zA-Z0-9_]+$",
);
export const bulkImportFactsBodyOneItemHashtagsDefault = [];
export const bulkImportFactsBodyOneItemHashtagsMax = 20;

export const bulkImportFactsBodyOneMax = 500;

export const bulkImportFactsBodyTwoFactsItemTextMin = 10;
export const bulkImportFactsBodyTwoFactsItemTextMax = 1000;

export const bulkImportFactsBodyTwoFactsItemHashtagsItemMax = 100;

export const bulkImportFactsBodyTwoFactsItemHashtagsItemRegExp = new RegExp(
  "^[a-zA-Z0-9_]+$",
);
export const bulkImportFactsBodyTwoFactsItemHashtagsDefault = [];
export const bulkImportFactsBodyTwoFactsItemHashtagsMax = 20;

export const bulkImportFactsBodyTwoFactsMax = 500;

export const BulkImportFactsBody = zod.union([
  zod
    .array(
      zod
        .object({
          text: zod
            .string()
            .min(bulkImportFactsBodyOneItemTextMin)
            .max(bulkImportFactsBodyOneItemTextMax)
            .describe("The fact text. Must be at least 10 characters."),
          hashtags: zod
            .array(
              zod
                .string()
                .max(bulkImportFactsBodyOneItemHashtagsItemMax)
                .regex(bulkImportFactsBodyOneItemHashtagsItemRegExp),
            )
            .max(bulkImportFactsBodyOneItemHashtagsMax)
            .default(bulkImportFactsBodyOneItemHashtagsDefault)
            .describe("Optional list of hashtag slugs to attach to this fact."),
        })
        .describe(
          "A single fact to import. The `text` field is required; `hashtags` is optional.",
        ),
    )
    .max(bulkImportFactsBodyOneMax),
  zod.object({
    facts: zod
      .array(
        zod
          .object({
            text: zod
              .string()
              .min(bulkImportFactsBodyTwoFactsItemTextMin)
              .max(bulkImportFactsBodyTwoFactsItemTextMax)
              .describe("The fact text. Must be at least 10 characters."),
            hashtags: zod
              .array(
                zod
                  .string()
                  .max(bulkImportFactsBodyTwoFactsItemHashtagsItemMax)
                  .regex(bulkImportFactsBodyTwoFactsItemHashtagsItemRegExp),
              )
              .max(bulkImportFactsBodyTwoFactsItemHashtagsMax)
              .default(bulkImportFactsBodyTwoFactsItemHashtagsDefault)
              .describe(
                "Optional list of hashtag slugs to attach to this fact.",
              ),
          })
          .describe(
            "A single fact to import. The `text` field is required; `hashtags` is optional.",
          ),
      )
      .max(bulkImportFactsBodyTwoFactsMax),
  }),
]);

export const BulkImportFactsResponse = zod
  .object({
    dryRun: zod
      .boolean()
      .optional()
      .describe("Present and true when the request was a dry run."),
    queued: zod
      .number()
      .int()
      .optional()
      .describe(
        "Number of facts queued as Stage-1 triage reviews (absent in dry-run mode).",
      ),
    skipped: zod
      .number()
      .int()
      .optional()
      .describe(
        "Number of valid facts skipped as exact-text duplicates against existing facts or unresolved reviews (absent in dry-run mode).",
      ),
    wouldQueue: zod
      .number()
      .int()
      .optional()
      .describe(
        "Number of facts that would be queued for moderation (dry-run mode only).",
      ),
    failed: zod
      .array(
        zod.object({
          index: zod
            .number()
            .int()
            .describe(
              "Zero-based position of the item in the submitted array.",
            ),
          errors: zod.array(
            zod.object({
              field: zod
                .string()
                .describe(
                  'The field that failed validation (e.g. "text", "hashtags.0").',
                ),
              message: zod
                .string()
                .describe("Human-readable reason the field failed validation."),
            }),
          ),
        }),
      )
      .describe("Items that failed schema validation and were not queued."),
  })
  .describe(
    "Result of a bulk import. Valid rows are QUEUED as Stage-1 moderation\nreviews, not inserted as facts directly (Phase 2 fact-lifecycle closure —\nbulk import loads the moderation queue, it does not publish). When\n`dryRun` is true, `wouldQueue` is present instead of `queued`/`skipped`.\n",
  );
